import pandas as pd
import numpy as np
import json
import base64
import io
from datetime import datetime

# ── Load & Prepare Data ──────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['Date'], dayfirst=False)
df = df.sort_values('Date').reset_index(drop=True)

# ── KPI Calculations ─────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
years = (last_date - first_date).days / 365.25

cumulative_return = (last_close / first_close - 1) * 100
cagr = ((last_close / first_close) ** (1 / years) - 1) * 100

df['daily_return'] = df['Close'].pct_change()
annualized_vol = df['daily_return'].std() * np.sqrt(252) * 100

# Maximum Drawdown
df['cummax'] = df['Close'].cummax()
df['drawdown'] = (df['Close'] - df['cummax']) / df['cummax']
max_drawdown = df['drawdown'].min() * 100
dd_end_idx = df['drawdown'].idxmin()
dd_end_date = df.loc[dd_end_idx, 'Date']
# find peak before trough
dd_peak_idx = df.loc[:dd_end_idx, 'Close'].idxmax()
dd_peak_date = df.loc[dd_peak_idx, 'Date']
dd_peak_price = df.loc[dd_peak_idx, 'Close']
dd_trough_price = df.loc[dd_end_idx, 'Close']

avg_volume = df['Volume'].mean()

# All-time high / low
ath_idx = df['Close'].idxmax()
ath_price = df.loc[ath_idx, 'Close']
ath_date = df.loc[ath_idx, 'Date']
atl_idx = df['Close'].idxmin()
atl_price = df.loc[atl_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date']

# ── Annual Performance ───────────────────────────────────────────────
df['Year'] = df['Date'].dt.year
annual = df.groupby('Year').agg(
    first_close=('Close', 'first'),
    last_close=('Close', 'last'),
    high=('High', 'max'),
    low=('Low', 'min'),
    avg_volume=('Volume', 'mean'),
    total_volume=('Volume', 'sum'),
    count=('Close', 'count')
).reset_index()
annual['return_pct'] = (annual['last_close'] / annual['first_close'] - 1) * 100

best_year = annual.loc[annual['return_pct'].idxmax()]
worst_year = annual.loc[annual['return_pct'].idxmin()]

# Decade performance
def decade_label(y):
    d = (y // 10) * 10
    return f"{d}s"

annual['decade'] = annual['Year'].apply(decade_label)
decade_perf = []
for dec, group in annual.groupby('decade'):
    start_price = group['first_close'].iloc[0]
    end_price = group['last_close'].iloc[-1]
    n_years = len(group)
    total_ret = (end_price / start_price - 1) * 100
    dec_cagr = ((end_price / start_price) ** (1 / n_years) - 1) * 100 if n_years > 0 else 0
    decade_perf.append({
        'decade': dec,
        'start_price': start_price,
        'end_price': end_price,
        'total_return': total_ret,
        'cagr': dec_cagr,
        'years': n_years
    })

# ── Rolling Volatility ───────────────────────────────────────────────
df['rolling_vol_60'] = df['daily_return'].rolling(60).std() * np.sqrt(252) * 100
df['daily_range_pct'] = (df['High'] - df['Low']) / df['Close'] * 100

# ── Monthly resampled for smoother charts ────────────────────────────
monthly = df.set_index('Date').resample('M').agg({
    'Close': 'last',
    'High': 'max',
    'Low': 'min',
    'Volume': 'mean',
    'daily_return': 'std',
    'daily_range_pct': 'mean'
}).dropna()
monthly['rolling_vol_ann'] = monthly['daily_return'] * np.sqrt(252) * 100

# ── Volume Analysis ──────────────────────────────────────────────────
df['vol_ma_50'] = df['Volume'].rolling(50).mean()
vol_spikes = df[df['Volume'] > df['vol_ma_50'] * 3].copy()
vol_spikes = vol_spikes.nlargest(10, 'Volume')

# ── Prepare chart data ───────────────────────────────────────────────
def fmt_date(d):
    return d.strftime('%Y-%m-%d')

# Price chart data (weekly for performance)
weekly = df.set_index('Date').resample('W').agg({
    'Close': 'last', 'High': 'max', 'Low': 'min', 'Volume': 'sum'
}).dropna()

price_dates = [fmt_date(d) for d in weekly.index]
price_vals = [round(v, 2) for v in weekly['Close'].values]

# Volume chart data (monthly)
monthly_vol = df.set_index('Date').resample('M')['Volume'].mean().dropna()
vol_dates = [fmt_date(d) for d in monthly_vol.index]
vol_vals = [round(v) for v in monthly_vol.values]

# Rolling volatility data (weekly)
weekly_vol_data = df.set_index('Date').resample('W')['rolling_vol_60'].last().dropna()
vol60_dates = [fmt_date(d) for d in weekly_vol_data.index]
vol60_vals = [round(v, 2) if not np.isnan(v) else None for v in weekly_vol_data.values]

# Annual returns for bar chart
annual_years = annual['Year'].tolist()
annual_returns = [round(v, 2) for v in annual['return_pct'].tolist()]

# Drawdown chart data (weekly)
weekly_dd = df.set_index('Date').resample('W')['drawdown'].last().dropna() * 100
dd_dates = [fmt_date(d) for d in weekly_dd.index]
dd_vals = [round(v, 2) for v in weekly_dd.values]

# Daily range chart (monthly avg)
monthly_range = df.set_index('Date').resample('M')['daily_range_pct'].mean().dropna()
range_dates = [fmt_date(d) for d in monthly_range.index]
range_vals = [round(v, 3) for v in monthly_range.values]

# ── Phase identification ─────────────────────────────────────────────
phases = []

# Identify major phases based on data
# 2000 decline
p2000_start = df[df['Date'] >= '2000-01-01'].iloc[0]
p2000_end = df[(df['Date'] >= '2002-09-01') & (df['Date'] <= '2002-10-31')].loc[df['Close'].idxmin()] if len(df[(df['Date'] >= '2002-09-01') & (df['Date'] <= '2002-10-31')]) > 0 else df[df['Date'] <= '2003-01-01'].iloc[-1]

# Find key turning points
yearly_prices = df.groupby('Year')['Close'].agg(['first', 'last', 'min', 'max']).reset_index()

# ── Build HTML ────────────────────────────────────────────────────────
# Volume spike table rows
vol_spike_rows = ""
for _, row in vol_spikes.iterrows():
    price_chg = row['daily_return'] * 100 if not np.isnan(row['daily_return']) else 0
    vol_spike_rows += f"""
    <tr>
        <td>{row['Date'].strftime('%b %d, %Y')}</td>
        <td>{row['Volume']:,.0f}</td>
        <td>${row['Close']:.2f}</td>
        <td class="{'positive' if price_chg >= 0 else 'negative'}">{price_chg:+.2f}%</td>
    </tr>"""

# Annual performance table
annual_rows = ""
for _, row in annual.iterrows():
    ret = row['return_pct']
    annual_rows += f"""
    <tr>
        <td>{int(row['Year'])}</td>
        <td>${row['first_close']:.2f}</td>
        <td>${row['last_close']:.2f}</td>
        <td>${row['high']:.2f}</td>
        <td>${row['low']:.2f}</td>
        <td class="{'positive' if ret >= 0 else 'negative'}">{ret:+.1f}%</td>
        <td>{row['avg_volume']:,.0f}</td>
    </tr>"""

# Decade performance table
decade_rows = ""
for dp in decade_perf:
    decade_rows += f"""
    <tr>
        <td>{dp['decade']}</td>
        <td>${dp['start_price']:.2f}</td>
        <td>${dp['end_price']:.2f}</td>
        <td class="{'positive' if dp['total_return'] >= 0 else 'negative'}">{dp['total_return']:+.1f}%</td>
        <td class="{'positive' if dp['cagr'] >= 0 else 'negative'}">{dp['cagr']:+.1f}%</td>
    </tr>"""

# Identify structural phases from the data
# Find local extremes in yearly data
phase_descriptions = []
# Early 2000s decline
early_low = df[(df['Date'] >= '2000-01-01') & (df['Date'] <= '2002-12-31')]['Close'].min()
early_low_date = df.loc[df[(df['Date'] >= '2000-01-01') & (df['Date'] <= '2002-12-31')]['Close'].idxmin(), 'Date']

# 2003-2007 bull run
mid_high = df[(df['Date'] >= '2003-01-01') & (df['Date'] <= '2008-01-01')]['Close'].max()
mid_high_date = df.loc[df[(df['Date'] >= '2003-01-01') & (df['Date'] <= '2008-01-01')]['Close'].idxmax(), 'Date']

# 2008 crisis
crisis_low = df[(df['Date'] >= '2008-01-01') & (df['Date'] <= '2009-12-31')]['Close'].min()
crisis_low_date = df.loc[df[(df['Date'] >= '2008-01-01') & (df['Date'] <= '2009-12-31')]['Close'].idxmin(), 'Date']

# 2009-2021 major bull
post_crisis_high = df[(df['Date'] >= '2009-01-01') & (df['Date'] <= '2021-12-31')]['Close'].max()
post_crisis_high_date = df.loc[df[(df['Date'] >= '2009-01-01') & (df['Date'] <= '2021-12-31')]['Close'].idxmax(), 'Date']

# 2022-2026 recent
recent_low = df[(df['Date'] >= '2022-01-01')]['Close'].min()
recent_low_date = df.loc[df[(df['Date'] >= '2022-01-01')]['Close'].idxmin(), 'Date']

# Positive vs negative years
pos_years = len(annual[annual['return_pct'] > 0])
neg_years = len(annual[annual['return_pct'] < 0])

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) Historical Stock Performance Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0/dist/chartjs-adapter-date-fns.bundle.min.js"></script>
<style>
  :root {{
    --bg: #fafbfc;
    --surface: #ffffff;
    --border: #e2e6ea;
    --text: #1a1a2e;
    --text-secondary: #5a6170;
    --accent: #0d47a1;
    --accent-light: #e3f2fd;
    --positive: #1b7a3d;
    --positive-bg: #e8f5e9;
    --negative: #c62828;
    --negative-bg: #ffebee;
    --chart-blue: #1565c0;
    --chart-blue-light: rgba(21, 101, 192, 0.12);
    --chart-orange: #e65100;
    --chart-green: #2e7d32;
    --chart-red: #c62828;
    --chart-gray: #78909c;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }}
  .container {{
    max-width: 1120px;
    margin: 0 auto;
    padding: 0 24px;
  }}
  header {{
    background: linear-gradient(135deg, #0d47a1 0%, #1565c0 50%, #1976d2 100%);
    color: white;
    padding: 48px 0 40px;
    margin-bottom: 32px;
  }}
  header h1 {{
    font-size: 28px;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }}
  header .subtitle {{
    font-size: 15px;
    opacity: 0.85;
    font-weight: 400;
  }}
  header .meta {{
    margin-top: 16px;
    font-size: 13px;
    opacity: 0.7;
  }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 40px;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px;
    text-align: center;
  }}
  .kpi-card .kpi-label {{
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--text-secondary);
    margin-bottom: 8px;
    font-weight: 600;
  }}
  .kpi-card .kpi-value {{
    font-size: 24px;
    font-weight: 700;
    color: var(--accent);
  }}
  .kpi-card .kpi-detail {{
    font-size: 12px;
    color: var(--text-secondary);
    margin-top: 4px;
  }}
  .kpi-card.positive .kpi-value {{ color: var(--positive); }}
  .kpi-card.negative .kpi-value {{ color: var(--negative); }}
  section {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 32px;
    margin-bottom: 24px;
  }}
  section h2 {{
    font-size: 20px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 4px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--accent-light);
  }}
  section h3 {{
    font-size: 16px;
    font-weight: 600;
    color: var(--text);
    margin: 24px 0 12px;
  }}
  section p {{
    color: var(--text-secondary);
    margin-bottom: 16px;
    font-size: 14.5px;
    line-height: 1.7;
  }}
  .chart-container {{
    position: relative;
    width: 100%;
    height: 380px;
    margin: 20px 0;
  }}
  .chart-container.tall {{
    height: 300px;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
    margin: 16px 0;
  }}
  table th {{
    background: var(--bg);
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-secondary);
    border-bottom: 2px solid var(--border);
  }}
  table td {{
    padding: 9px 12px;
    border-bottom: 1px solid var(--border);
  }}
  table tr:hover {{
    background: var(--bg);
  }}
  td.positive {{ color: var(--positive); font-weight: 600; }}
  td.negative {{ color: var(--negative); font-weight: 600; }}
  .phase-timeline {{
    margin: 20px 0;
  }}
  .phase {{
    display: flex;
    align-items: flex-start;
    margin-bottom: 16px;
    padding: 16px;
    border-radius: 6px;
    border-left: 4px solid var(--accent);
    background: var(--bg);
  }}
  .phase.bear {{
    border-left-color: var(--negative);
  }}
  .phase.bull {{
    border-left-color: var(--positive);
  }}
  .phase .phase-period {{
    font-weight: 700;
    font-size: 14px;
    min-width: 140px;
