<body>

<header>
  <div class="container">
    <h1>Nike Inc. (NKE) Historical Stock Performance Analysis</h1>
    <div class="subtitle">A comprehensive analysis of stock price trends, volatility, and trading volume over 26 years (2000&ndash;2026)</div>
    <div class="meta">Data Period: {first_date.strftime('%B %d, %Y')} &ndash; {last_date.strftime('%B %d, %Y')} &nbsp;|&nbsp; {len(df):,} Trading Days &nbsp;|&nbsp; Prices are split- and dividend-adjusted</div>
  </div>
</header>

<div class="container">

<!-- KPI Dashboard -->
<div class="kpi-grid">
  <div class="kpi-card positive">
    <div class="kpi-label">Cumulative Return</div>
    <div class="kpi-value">{cumulative_return:,.1f}%</div>
    <div class="kpi-detail">${first_close:.2f} &rarr; ${last_close:.2f}</div>
  </div>
  <div class="kpi-card positive">
    <div class="kpi-label">CAGR</div>
    <div class="kpi-value">{cagr:.1f}%</div>
    <div class="kpi-detail">Over {years:.1f} years</div>
  </div>
  <div class="kpi-card negative">
    <div class="kpi-label">Maximum Drawdown</div>
    <div class="kpi-value">{max_drawdown:.1f}%</div>
    <div class="kpi-detail">{dd_peak_date.strftime('%b %Y')} &rarr; {dd_end_date.strftime('%b %Y')}</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Annualized Volatility</div>
    <div class="kpi-value">{annualized_vol:.1f}%</div>
    <div class="kpi-detail">Based on daily returns</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Avg Daily Volume</div>
    <div class="kpi-value">{avg_volume/1e6:.1f}M</div>
    <div class="kpi-detail">shares per day</div>
  </div>
</div>

<!-- Executive Summary -->
<section id="executive-summary">
  <h2>Executive Summary</h2>
  <p>
