import pandas as pd
import numpy as np
import json
import base64
import io
from datetime import datetime

# ── Load & Prepare Data ──────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['Date'], dayfirst=False)
df = df.sort_values('Date').reset_index(drop=True)

# ── KPI Calculations ─────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
years = (last_date - first_date).days / 365.25

cumulative_return = (last_close / first_close - 1) * 100
cagr = ((last_close / first_close) ** (1 / years) - 1) * 100

df['daily_return'] = df['Close'].pct_change()
annualized_vol = df['daily_return'].std() * np.sqrt(252) * 100

# Maximum Drawdown
df['cummax'] = df['Close'].cummax()
df['drawdown'] = (df['Close'] - df['cummax']) / df['cummax']
max_drawdown = df['drawdown'].min() * 100
dd_end_idx = df['drawdown'].idxmin()
dd_end_date = df.loc[dd_end_idx, 'Date']
# find peak before trough
dd_peak_idx = df.loc[:dd_end_idx, 'Close'].idxmax()
dd_peak_date = df.loc[dd_peak_idx, 'Date']
dd_peak_price = df.loc[dd_peak_idx, 'Close']
dd_trough_price = df.loc[dd_end_idx, 'Close']

avg_volume = df['Volume'].mean()

# All-time high / low
ath_idx = df['Close'].idxmax()
ath_price = df.loc[ath_idx, 'Close']
ath_date = df.loc[ath_idx, 'Date']
atl_idx = df['Close'].idxmin()
atl_price = df.loc[atl_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date']

# ── Annual Performance ───────────────────────────────────────────────
df['Year'] = df['Date'].dt.year
annual = df.groupby('Year').agg(
    first_close=('Close', 'first'),
    last_close=('Close', 'last'),
    high=('High', 'max'),
    low=('Low', 'min'),
    avg_volume=('Volume', 'mean'),
    total_volume=('Volume', 'sum'),
    count=('Close', 'count')
).reset_index()
annual['return_pct'] = (annual['last_close'] / annual['first_close'] - 1) * 100

best_year = annual.loc[annual['return_pct'].idxmax()]
worst_year = annual.loc[annual['return_pct'].idxmin()]

# Decade performance
def decade_label(y):
    d = (y // 10) * 10
    return f"{d}s"

annual['decade'] = annual['Year'].apply(decade_label)
decade_perf = []
for dec, group in annual.groupby('decade'):
    start_price = group['first_close'].iloc[0]
    end_price = group['last_close'].iloc[-1]
    n_years = len(group)
    total_ret = (end_price / start_price - 1) * 100
    dec_cagr = ((end_price / start_price) ** (1 / n_years) - 1) * 100 if n_years > 0 else 0
    decade_perf.append({
        'decade': dec,
        'start_price': start_price,
        'end_price': end_price,
        'total_return': total_ret,
        'cagr': dec_cagr,
        'years': n_years
    })

# ── Rolling Volatility ───────────────────────────────────────────────
df['rolling_vol_60'] = df['daily_return'].rolling(60).std() * np.sqrt(252) * 100
df['daily_range_pct'] = (df['High'] - df['Low']) / df['Close'] * 100

# ── Monthly resampled for smoother charts ────────────────────────────
monthly = df.set_index('Date').resample('M').agg({
    'Close': 'last',
    'High': 'max',
    'Low': 'min',
    'Volume': 'mean',
    'daily_return': 'std',
    'daily_range_pct': 'mean'
}).dropna()
monthly['rolling_vol_ann'] = monthly['daily_return'] * np.sqrt(252) * 100

# ── Volume Analysis ──────────────────────────────────────────────────
df['vol_ma_50'] = df['Volume'].rolling(50).mean()
vol_spikes = df[df['Volume'] > df['vol_ma_50'] * 3].copy()
vol_spikes = vol_spikes.nlargest(10, 'Volume')

# ── Prepare chart data ───────────────────────────────────────────────
def fmt_date(d):
    return d.strftime('%Y-%m-%d')

# Price chart data (weekly for performance)
weekly = df.set_index('Date').resample('W').agg({
    'Close': 'last', 'High': 'max', 'Low': 'min', 'Volume': 'sum'
}).dropna()

price_dates = [fmt_date(d) for d in weekly.index]
price_vals = [round(v, 2) for v in weekly['Close'].values]

# Volume chart data (monthly)
monthly_vol = df.set_index('Date').resample('M')['Volume'].mean().dropna()
vol_dates = [fmt_date(d) for d in monthly_vol.index]
vol_vals = [round(v) for v in monthly_vol.values]

# Rolling volatility data (weekly)
weekly_vol_data = df.set_index('Date').resample('W')['rolling_vol_60'].last().dropna()
vol60_dates = [fmt_date(d) for d in weekly_vol_data.index]
vol60_vals = [round(v, 2) if not np.isnan(v) else None for v in weekly_vol_data.values]

# Annual returns for bar chart
annual_years = annual['Year'].tolist()
annual_returns = [round(v, 2) for v in annual['return_pct'].tolist()]

# Drawdown chart data (weekly)
weekly_dd = df.set_index('Date').resample('W')['drawdown'].last().dropna() * 100
dd_dates = [fmt_date(d) for d in weekly_dd.index]
dd_vals = [round(v, 2) for v in weekly_dd.values]

# Daily range chart (monthly avg)
monthly_range = df.set_index('Date').resample('M')['daily_range_pct'].mean().dropna()
